(21903, 'plPL', 'Wykrój: naramienniki z tkaniny dusz', 'Uczy szycia naramienników z tkaniny dusz.', 0),
(21904, 'plPL', 'Wykrój: kamizelka z tkaniny dusz', 'Uczy szycia kamizelki z tkaniny dusz.', 0),
(22535, 'plPL', 'Formuła: zaklęcie pierścienia – uderzenie', 'Uczy trwałego zaklinania pierścienia, by zwiększał obrażenia fizyczne o 2. Zaklinać można tylko własne pierścienie zaklinacza, a zaklęty pierścień staje się związany z duszą. Wymaga przedmiotu na poziomie 35 lub wyższym.', 0),
(22545, 'plPL', 'Formuła: zaklęcie butów – pewny krok', 'Uczy trwałego zaklinania butów, by zwiększały wskaźnik trafienia i wskaźnik trafienia krytycznego o 10. Wymaga przedmiotu na poziomie 35 lub wyższym.', 0),
(22559, 'plPL', 'Formuła: zaklęcie broni – mangusta', 'Uczy trwałego zaklinania broni do walki wręcz, by od czasu do czasu zwiększała zręczność o 120 i nieznacznie szybkość ataku. Wymaga przedmiotu na poziomie 35 lub wyższym.', 0),
(22560, 'plPL', 'Formuła: zaklęcie broni – ogień słońca', 'Uczy trwałego zaklinania broni do walki wręcz, by zwiększała moc czarów ognia i tajemnej mocy o 50. Wymaga przedmiotu na poziomie 35 lub wyższym.', 0),
(22561, 'plPL', 'Formuła: zaklęcie broni – mróz duszy', 'Uczy trwałego zaklinania broni do walki wręcz, by zwiększała moc czarów mrozu i cienia o 54. Wymaga przedmiotu na poziomie 35 lub wyższym.', 0),
(23857, 'plPL', 'Dziedzictwo górskiego króla', 'Esencja tej księgi jest związana z Karazhanem.', 0),
