INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(16504, 1, 0, 'plPL', 'To... niczego nie zmienia. Czeka was wieczne potępienie!'),
(16540, 0, 2, 'plPL', 'Sekrety tego miejsca nie są dla takich jak wy!'),
(16544, 0, 2, 'plPL', 'Sekrety tego miejsca nie są dla takich jak wy!'),
(16545, 0, 2, 'plPL', 'Sekrety tego miejsca nie są dla takich jak wy!'),
(16816, 0, 0, 'plPL', 'Dobrze więc. Niech gra się zacznie.'),
(16816, 1, 0, 'plPL', 'Może czas na zmianę.'),
(16816, 1, 1, 'plPL', 'Pora na inny scenariusz.'),
(16816, 1, 2, 'plPL', 'Nie wolno popadać w zbytnie samozadowolenie.'),
(16816, 3, 0, 'plPL', 'Zobaczmy.'),
(16816, 3, 1, 'plPL', 'Przejrzysta strategia.'),
(16816, 3, 2, 'plPL', 'Ach, tryby zaczęły się obracać.'),
(16816, 4, 0, 'plPL', 'Głupio! Bardzo głupio!'),
(16816, 5, 0, 'plPL', 'Tak... wszystko zgodnie z planem.'),
(16816, 6, 0, 'plPL', 'Wystarczy najmniejsza chwila nieuwagi.'),
(16816, 7, 0, 'plPL', 'Teraz zaczyna się robić ciekawie.'),
(16816, 9, 1, 'plPL', 'Nieważne.'),
(16816, 10, 0, 'plPL', 'Drobny kłopot.'),
(16816, 11, 0, 'plPL', 'Tak... oczywiście.'),
(16816, 12, 0, 'plPL', 'Konieczna ofiara.'),
(16816, 13, 0, 'plPL', 'Ach, powinienem był się domyślić.'),
(16816, 14, 0, 'plPL', 'I tak oto koniec się zbliża'),
(16816, 15, 0, 'plPL', 'Nic poza perfekcją nie wystarczy.'),
(16816, 15, 1, 'plPL', 'I tak to się kończy.');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(12059, 'plPL', 'Witajcie, podróżni. Polecono mi traktować każdego, kto ma klucz do Karazhanu, jak honorowego gościa Mistrza. Śmiało pytajcie mnie, o co chcecie. W czym mogę pomóc?', '', 0),
(12064, 'plPL', 'Ach, goście Mistrza. Mam nadzieję, że uważacie tu, gdzie stawiacie kroki.', '', 0),
(12073, 'plPL', 'Niech szlag trafi to robactwo! Pewnie nie zechcecie mi pomóc w tej sytuacji?', '', 0),
(13202, 'plPL', 'Mistrz jest pogrążony w studiach.', '', 0),
(13203, 'plPL', 'Mistrz odpoczywa po swoich trudach.', '', 0),
(13204, 'plPL', 'Mistrz wkrótce wróci z Wichrogrodu...', '', 0),
(13205, 'plPL', 'Mistrz ma sprawy w komnatach na górze.', '', 0),
(13206, 'plPL', 'Mistrz spotyka się ze swoim uczniem.', '', 0),
(13229, 'plPL', 'Jestem tak napchany, że nie przełknę już ani kęsa! No, może jeszcze jeden...', 'Jestem tak napchany, że nie przełknę już ani kęsa! No, może jeszcze jeden...\n', 0),
(13234, 'plPL', 'Uczta godna królów!', 'Uczta godna królów!', 0),
(13235, 'plPL', 'A on na to: „Ja mówiłem do kurczaka!”', 'A on na to: „Ja mówiłem do kurczaka!”', 0),
(13236, 'plPL', 'Ten dowcip mnie dobija!', 'Ten dowcip mnie dobija!', 0),
(13237, 'plPL', 'Czy ktoś jeszcze pamięta, jak się tu znaleźliśmy? Czy tylko ja...?', 'Czy ktoś jeszcze pamięta, jak się tu znaleźliśmy? Czy tylko ja...?', 0),
(13238, 'plPL', 'Gdzie mieszkałem, zanim tu trafiłem? Kiedyś wiedziałem. A przynajmniej tak mi się zdawało...', 'Gdzie mieszkałem, zanim tu trafiłem? Kiedyś wiedziałem. A przynajmniej tak mi się zdawało...', 0),
(13239, 'plPL', 'Ach, życie jest piękne.', 'Ach, życie jest piękne.', 0),
(13240, 'plPL', 'Nigdy nie byłem tak szczęśliwy! Chciałbym, żeby ta noc nigdy się nie skończyła!', 'Nigdy nie byłem tak szczęśliwy! Chciałbym, żeby ta noc nigdy się nie skończyła!', 0),
(13241, 'plPL', 'Kelner, jeszcze jedno piwo!', 'Kelner, jeszcze jedno piwo!', 0),
(13242, 'plPL', 'Kelner, więcej wina!', 'Kelner, więcej wina!', 0),
(13243, 'plPL', 'Kelner, gdzie mój zając w potrawce?', 'Kelner, gdzie mój zając w potrawce?', 0),
(13244, 'plPL', 'Z przyjemnością.', '', 0),
(13245, 'plPL', 'Już się robi, panie.', '', 0),
(13246, 'plPL', 'Zaraz to sprawdzę.', '', 0),
(13278, 'plPL', 'Kelner, jeszcze jedną butelkę, i to migiem!', 'Kelner, jeszcze jedną butelkę, i to migiem!', 0),
(13279, 'plPL', 'Oczywiście, panie.', '', 0),
(13284, 'plPL', 'Za nic w świecie nie wiem, czemu tu jestem, ale bawię się wyśmienicie!', 'Za nic w świecie nie wiem, czemu tu jestem, ale bawię się wyśmienicie!', 0),
(13293, 'plPL', 'Więcej jedzenia! Więcej wina!', 'Więcej jedzenia! Więcej wina!', 0),
(13294, 'plPL', 'Tym razem chyba spróbuję merlota.', 'Tym razem chyba spróbuję merlota.', 0),
(13296, 'plPL', 'Bez zwłoki!', 'Bez zwłoki!', 0),
(13298, 'plPL', 'Nie żałujcie trunków, to będzie długa noc!', 'Nie żałujcie trunków, to będzie długa noc!', 0),
(13336, 'plPL', 'To wszystko wydaje się takie znajome, jakbym już tu kiedyś był.', 'To wszystko wydaje się takie znajome, jakbym już tu kiedyś był.', 0),
(13337, 'plPL', 'Może później przyłączymy się do tańców.', 'Może później przyłączymy się do tańców.', 0),
(13396, 'plPL', '', 'Twoja nieczystość musi zostać oczyszczona.', 0),
(13398, 'plPL', 'Hej! A ty dokąd się tak skradasz?', 'Hej! A ty dokąd się tak skradasz?', 0),
(13399, 'plPL', 'Przepraszam, czy próbujesz się prześlizgnąć bez zaproszenia?', 'Przepraszam, czy próbujesz się prześlizgnąć bez zaproszenia?', 0),
(13435, 'plPL', 'Jak śmiesz rozlewać wino Mistrza!', 'Jak śmiesz rozlewać wino Mistrza!', 0),
(13436, 'plPL', 'To było dwustuletnie Porto Pupellyverbos!', 'To było dwustuletnie Porto Pupellyverbos!', 0),
(13437, 'plPL', 'Zmarnowane na takich jak ty!', 'Zmarnowane na takich jak ty!', 0),
(13438, 'plPL', 'Jak śmiesz przeszkadzać Mistrzowi w kolacji!', 'Jak śmiesz przeszkadzać Mistrzowi w kolacji!', 0),
(13439, 'plPL', '%s wzywa swojego pana!', '%s wzywa swojego pana!', 0),
(13449, 'plPL', 'Aktywacja trybu obronnego EL-7M.', '', 0),
(13450, 'plPL', 'Aktywacja trybu obronnego EL-5R.', '', 0),
(13451, 'plPL', 'Aktywacja trybu obronnego EL-2S.', '', 0),
(13455, 'plPL', '%s rusza na pomoc swojemu panu.', '%s rusza na pomoc swojemu panu.', 0),
(13461, 'plPL', 'Jeszcze jeden gość na dzisiejszą kolację.', '', 0),
(13513, 'plPL', 'Jeszcze nie skończyłem! O nie, mam w zanadrzu jeszcze kilka sztuczek...', '', 0),
(13514, 'plPL', 'Chyba nie odmówisz staruszkowi orzeźwiającego napitku? Nie, nie, tak myślałem.', '', 0),
(13515, 'plPL', '%s zaczyna przelewać swoją manę w potężne tajemne zaklęcie.', '', 0),
(13517, 'plPL', 'Tak, tak, mój syn jest bardzo potężny... ale ja też mam swoje moce!', '', 0),
(13518, 'plPL', 'Nie jestem jakimś prostym błaznem! Jestem Nielas Aran!', '', 0),
(13519, 'plPL', 'Pokażę wam: ten zbity pies ma jeszcze zęby!', '', 0),
(13520, 'plPL', 'Płońcie, piekielne pomioty!', '', 0),
(13522, 'plPL', 'Zamrożę was wszystkich!', '', 0),
(13526, 'plPL', 'Chcę, żeby ten koszmar się skończył!', '', 0),
(13527, 'plPL', 'Nie dręczcie mnie więcej!', '', 0),
(13529, 'plPL', 'Proszę, dość! Mój syn... postradał zmysły!', '', 0),
(13530, 'plPL', 'Kim jesteście? Czego chcecie? Nie zbliżajcie się do mnie!', '', 0),
(13532, 'plPL', 'Skąd to macie? Czy to ON was przysłał?', '', 0),
(13569, 'plPL', 'Zmarnowaliście już dość mojego czasu... niech te gry się skończą!', '', 0),
(13647, 'plPL', 'W oddali budzi się prastara istota...', '', 0),
(13649, 'plPL', 'Co za głupcy! Szybko położę kres waszym cierpieniom!', '', 0),
(13676, 'plPL', 'Dość! Wyląduję i sam was zmiażdżę!', '', 0),
(13677, 'plPL', 'Insekty! Pokażę wam swoją siłę z bliska!', '', 0),
(13773, 'plPL', 'Intruz!', 'Intruz!', 0),
(13774, 'plPL', 'Nie jesteś tu $gmile widziany:mile widziana;!', 'Nie jesteś tu $gmile widziany:mile widziana;!', 0),
(13789, 'plPL', 'Czy to koniec?', 'Czy to koniec?', 0),
(13790, 'plPL', 'Co się stanie z...', 'Co się stanie z...', 0),
(13798, 'plPL', 'Ty, stój!', 'Ty, stój!', 0),
(13801, 'plPL', 'Zgubiłem się...', 'Zgubiłem się...', 0),
(13802, 'plPL', 'Dlaczego...?', 'Dlaczego...?', 0),
(13804, 'plPL', 'Kolejny dzień, kolejna stajnia do wymucenia.', 'Kolejny dzień, kolejna stajnia do wymucenia.', 0),
(13805, 'plPL', 'Mam dość tej rutyny.', 'Mam dość tej rutyny.', 0),
(13806, 'plPL', '<westchnienie> Mam wrażenie, że robię to od zawsze...', '<westchnienie> Mam wrażenie, że robię to od zawsze...', 0),
(13821, 'plPL', 'Najeźdźcy w wieży!', 'Najeźdźcy w wieży!', 0),
(13822, 'plPL', 'Zatrzymać ich!', 'Zatrzymać ich!', 0),
(13823, 'plPL', 'Już po mnie!', 'Już po mnie!', 0),
(13825, 'plPL', 'Mistrz... będzie zły...', 'Mistrz... będzie zły...', 0),
(13826, 'plPL', 'Jeśli będziemy się dłużej guzdrać, będzie piekło!\n', 'Jeśli będziemy się dłużej guzdrać, będzie piekło!', 0),
(13827, 'plPL', 'Reszta poradzi sobie bez nas.', 'Reszta poradzi sobie bez nas.', 0),
(13828, 'plPL', 'Nawet nie zauważą, że nas nie ma.', 'Nawet nie zauważą, że nas nie ma.', 0),
(13829, 'plPL', 'Do broni!', 'Do broni!', 0),
(13830, 'plPL', 'Bronić wieży!', 'Bronić wieży!', 0),
(13831, 'plPL', 'Na nich!', 'Na nich!', 0),
(13834, 'plPL', 'Zawiodłem...', 'Zawiodłem...', 0),
(13835, 'plPL', 'Zostaniesz $gukarany:ukarana;!', 'Zostaniesz $gukarany:ukarana;!', 0),
(13836, 'plPL', 'Za... płacisz... mi.', 'Za... płacisz... mi.', 0),
(13838, 'plPL', 'Jak śmiesz się wtrącać?!', 'Jak śmiesz się wtrącać?!', 0),
(13839, 'plPL', 'Nie masz tu czego szukać!', 'Nie masz tu czego szukać!', 0),
(13840, 'plPL', 'Zostawcie nas! Dajcie nam spokój!', 'Zostawcie nas! Dajcie nam spokój!', 0),
(13841, 'plPL', 'To... niesprawiedliwe...', 'To... niesprawiedliwe...', 0),
(13842, 'plPL', 'To jeszcze nie mój czas, jeszcze nie!', 'To jeszcze nie mój czas, jeszcze nie!', 0),
(13843, 'plPL', 'Wszystko, co dobre, kiedyś się kończy.', 'Wszystko, co dobre, kiedyś się kończy.', 0),
(13844, 'plPL', 'Wszystko zepsujesz!', 'Wszystko zepsujesz!', 0),
(13845, 'plPL', 'Precz stąd!', 'Precz stąd!', 0),
(13846, 'plPL', 'Nie życzymy sobie, by nam przeszkadzano!', 'Nie życzymy sobie, by nam przeszkadzano!', 0),
(13847, 'plPL', 'Gdzie ja jestem? Co...', 'Gdzie ja jestem? Co...', 0),
(13848, 'plPL', 'Co się dzieje?', 'Co się dzieje?', 0),
(13849, 'plPL', 'Nie wolno mi się bać...', 'Nie wolno mi się bać...', 0),
(13851, 'plPL', 'Precz, obcy!', 'Precz, obcy!', 0),
(13852, 'plPL', 'Nie zepsujesz nam zabawy!', 'Nie zepsujesz nam zabawy!', 0),
(13853, 'plPL', 'Jesteśmy oblężeni!', 'Jesteśmy oblężeni!', 0),
(13856, 'plPL', 'Los obrócił się przeciwko mnie!', 'Los obrócił się przeciwko mnie!', 0),
(13857, 'plPL', 'Mój czas się skończył.', 'Mój czas się skończył.', 0),
(13858, 'plPL', 'Nie, nie teraz! Nie w ten sposób!', 'Nie, nie teraz! Nie w ten sposób!', 0),
(13861, 'plPL', 'Posiekam cię na mielone!', 'Posiekam cię na mielone!', 0),
(13862, 'plPL', 'Wypatroszę cię jak rybę!', 'Wypatroszę cię jak rybę!', 0),
(13864, 'plPL', 'Służyłem do samego końca...', 'Służyłem do samego końca...', 0),
(13865, 'plPL', 'To nie koniec, to nie może być koniec!', 'To nie koniec, to nie może być koniec!', 0),
(13866, 'plPL', 'Starałem się, mistrzu. Starałem się.', 'Starałem się, mistrzu. Starałem się.', 0),
(13876, 'plPL', 'Bezczelni obcy!', 'Bezczelni obcy!', 0),
(13877, 'plPL', 'Wścibscy głupcy! Zapłacicie życiem!', 'Wścibscy głupcy! Zapłacicie życiem!', 0),
(13879, 'plPL', 'Nie wyjdziecie stąd żywi...', 'Nie wyjdziecie stąd żywi...', 0),
(13880, 'plPL', '', 'Chodź, pobaw się ze mną!', 0),
(13881, 'plPL', '', 'BĘDZIESZ $gmój:moja;.', 0),
(13882, 'plPL', '', 'Chodź tu, ślicznotko. Masz to, czego mi trzeba!', 0),
(13883, 'plPL', '', 'No to mówię: „Jasne, ale to kosztuje ekstra”.', 0),
(13884, 'plPL', '', 'Pięć sekund. Nie żartuję!', 0),
(13885, 'plPL', '', 'Zapytał, czy chochlik może się przyłączyć – wyobrażasz sobie? Właściwie nie było to wcale takie złe...', 0),
(13886, 'plPL', '', 'Oni zasypiają po. Ja zasypiam w trakcie...', 0),
(13887, 'plPL', '', 'Podejdź bliżej, a zacznę krzyczeć.', 0),
(13888, 'plPL', '', 'Chcę ci pokazać moje inne oblicze...', 0),
(13889, 'plPL', '', 'Fajnie było, póki trwało...', 0),
(13890, 'plPL', '', '<westchnienie> Zawsze kończy się za szybko.', 0),
(13891, 'plPL', '', 'Chcę, żebyś $gbył:była; ze mną... na zawsze.', 0),
(13892, 'plPL', '', 'Ciii... mam mały sekret, którego strzegę.\n', 0),
(13895, 'plPL', '', 'Byłam bardzo, bardzo niegrzeczna...', 0),
(13896, 'plPL', '', 'Dość gry wstępnej. Przejdźmy do rzeczy.', 0),
(13897, 'plPL', '', 'Akurat kiedy zaczynało się robić ciekawie.', 0),
(13898, 'plPL', '', 'Mogliśmy się tak świetnie zabawić!', 0),
(13916, 'plPL', 'Nie wolno ci się wtrącać!', 'Nie wolno ci się wtrącać!', 0),
(13917, 'plPL', 'Co ty robisz? Zmykaj!', 'Co ty robisz? Zmykaj!', 0),
(13918, 'plPL', 'Przegapię przedstawienie!', 'Przegapię przedstawienie!', 0),
(13919, 'plPL', 'Tak, chyba już sobie przypominam...', 'Tak, chyba już sobie przypominam...', 0),
(13920, 'plPL', 'Odsunąć się!', '', 0),
(13921, 'plPL', 'Gdzie twój bilet?', '', 0),
(13922, 'plPL', 'Przedstawienie jest tylko dla gości!', '', 0),
(13923, 'plPL', 'Nie trzeba było tu przychodzić!', '', 0),
(13924, 'plPL', 'Teraz dołączysz do pozostałych gości...', '', 0),
(13928, 'plPL', 'Nie wolno ci tu wchodzić!', 'Nie wolno ci tu wchodzić!', 0),
(13929, 'plPL', 'Nie jesteś gościem!', 'Nie jesteś gościem!', 0),
(13930, 'plPL', 'Czy jestem zwolniony z obowiązków?', 'Czy jestem zwolniony z obowiązków?', 0),
(13931, 'plPL', 'Nareszcie moja praca skończona.', 'Nareszcie moja praca skończona.', 0),
(13932, 'plPL', 'Żwawo, mistrz na nas liczy!', 'Żwawo, mistrz na nas liczy!', 0),
(13934, 'plPL', 'Ile zmian dekoracji? Pewnie tyle co ostatnio.', 'Ile zmian dekoracji? Pewnie tyle co ostatnio.', 0),
(13938, 'plPL', 'Nie pozwolę, żeby amatorzy przyćmili mnie na scenie!', 'Nie pozwolę, żeby amatorzy przyćmili mnie na scenie!', 0),
(13939, 'plPL', 'Przedstawienie musi trwać!', 'Przedstawienie musi trwać!', 0),
(13940, 'plPL', 'Tak zimno, tak ciemno... Chyba nie przesadzam z grą?', 'Tak zimno, tak ciemno... Chyba nie przesadzam z grą?', 0),
(13941, 'plPL', 'Dopilnujcie, żeby na nagrobku dobrze napisali moje nazwi...', 'Dopilnujcie, żeby na nagrobku dobrze napisali moje nazwi...', 0),
(13942, 'plPL', 'Nie będziemy tolerować twojej bezczelności!', 'Nie będziemy tolerować twojej bezczelności!', 0),
(13943, 'plPL', 'Nie było cię na liście gości!', 'Nie było cię na liście gości!', 0),
(13944, 'plPL', 'Wszystko... wraca do mnie...', 'Wszystko... wraca do mnie...', 0),
(13945, 'plPL', 'Czy to naprawdę koniec?', 'Czy to naprawdę koniec?', 0),
(13946, 'plPL', 'Nie znajdziesz tu nagrody, tylko śmierć!', '', 0),
(13947, 'plPL', 'Odwiedzającym wstęp wzbroniony!', '', 0),
(13948, 'plPL', 'Wolny... nareszcie.', '', 0),
(13949, 'plPL', 'Czas ruszać dalej.', '', 0),
(13951, 'plPL', 'Złodzieje! Zatrzymać ich!', '', 0),
(13952, 'plPL', 'Stój natychmiast!', '', 0),
(13953, 'plPL', 'Grabieżcy! Bezcześciciele!', '', 0),
(13954, 'plPL', 'Ten sam los czeka każdego, kto zechce okraść mistrza.', '', 0),
(13955, 'plPL', 'Śmierć to dla takich jak wy zbyt wielka łaska.', '', 0),
(13956, 'plPL', 'Nie wyjdziecie stąd żywi!', '', 0),
(13957, 'plPL', 'Inni zajmą moje miejsce!', '', 0),
(13958, 'plPL', 'To... niczego nie zmienia. Czeka was wieczne potępienie!\n', '', 0),
(13960, 'plPL', 'Nie! Byliśmy tu pierwsi!', 'Nie! Byliśmy tu pierwsi!', 0),
(13961, 'plPL', 'Sekrety biblioteki należą do nas i tylko do nas!', 'Sekrety biblioteki należą do nas i tylko do nas!', 0),
(13964, 'plPL', 'Strzeżcie się... wyższych pięter.', 'Strzeżcie się... wyższych pięter.', 0),
(13965, 'plPL', 'Zawróćcie, póki możecie.', 'Zawróćcie, póki możecie.', 0),
(13968, 'plPL', 'Amatorzy! Porywacie się z motyką na słońce!', '', 0),
(13969, 'plPL', 'Wieża to nie miejsce dla niewtajemniczonych!', '', 0),
(13972, 'plPL', 'Ściągniecie na siebie jedynie potępienie!', '', 0),
(14002, 'plPL', '<Piechur stoi niewzruszony, z napiętymi mięśniami.>', '', 0),
(14051, 'plPL', 'Nareszcie wszystko gotowe. Jesteś $ggotów:gotowa; na swój wielki debiut na scenie?', '', 0),
(14052, 'plPL', 'Nie jestem $gaktorem:aktorką;.', 'Nie jestem $gaktorem:aktorką;.', 0),
(14057, 'plPL', 'Dobry wieczór, panie i panowie, witamy na dzisiejszym przedstawieniu!', '', 0),
(14122, 'plPL', 'Witamy, panie i panowie, na dzisiejszym przedstawieniu!', '', 0),
(15021, 'plPL', 'Hm, niezapowiedziani goście. Trzeba poczynić przygotowania...', '', 0),
(15022, 'plPL', 'Ależ okropna ze mnie niezdara.', '', 0),
(15055, 'plPL', 'Menażeria jest tylko dla gości.', '', 0),
(15057, 'plPL', 'Kustosz nie jest już spraw-n-y.', '', 0),
(15059, 'plPL', 'Twoje żądanie nie może zostać przetworzone.', '', 0),
(15060, 'plPL', 'Brak posłuszeństwa spowoduje działania ofensywne.', '', 0),
(15079, 'plPL', '', 'Twoje zachowanie nie będzie tolerowane.', 0),
(15080, 'plPL', '', 'Odrzuć swoje zepsute myśli.', 0),
(15081, 'plPL', '', 'Nadchodzi śmierć. Czy twoje sumienie będzie czyste?', 0),
(15082, 'plPL', '', 'Ach, ach, ach...', 0),
(15083, 'plPL', '', 'Nieczyste myśli prowadzą do bluźnierczych czynów.', 0),
(15084, 'plPL', '', 'Tak będzie najlepiej.', 0),
(15085, 'plPL', 'Czas... zawsze za mało czasu.', '', 0),
(15086, 'plPL', 'Och, ależ narobiłem bałaganu...', '', 0),
(15137, 'plPL', 'Moje życie należy do ciebie, o wielki...', '', 0),
(15141, 'plPL', 'Ach, w samą porę. Rytuały zaraz się zaczną!', '', 0),
(15145, 'plPL', 'Twoja krew namaści mój krąg!', '', 0),
(15146, 'plPL', 'Wielki będzie zadowolony.', '', 0),
(15147, 'plPL', 'Przyjmij tę skromną ofiarę, o wielki...', '', 0),
(15148, 'plPL', 'Niech ta ofiara będzie świadectwem mojej wierności.', '', 0),
(15150, 'plPL', 'Przybywajcie, mieszkańcy mroku! Na moje wezwanie!', '', 0),
(15151, 'plPL', 'Zbierajcie się, moje pupilki... starczy dla wszystkich!', '', 0),
(15335, 'plPL', 'Nie dotykać eksponatów.', '', 0),
(15336, 'plPL', 'Nie jesteś gościem.', '', 0),
(15337, 'plPL', 'Regulamin galerii będzie ściśle egzekwowany.', '', 0),
(15338, 'plPL', 'Ten Kustosz jest wyposażony do ochrony galerii.', '', 0),
(15339, 'plPL', 'Na czym to ja skończyłem? A, tak...', '', 0),
(15340, 'plPL', 'Wzywano mnie?', '', 0),
(15345, 'plPL', 'Nareszcie koszmar się skończył...', '', 0),
(15353, 'plPL', 'Nie pozwolę się znowu torturować!', '', 0),
(15359, 'plPL', 'Dziś wieczorem nic nie jest takie, jakim się wydaje... bo dziś nie możecie ufać własnym oczom!', '', 0),
(15360, 'plPL', 'Weźmy na przykład tę cichą staruszkę, która czeka na odwiedziny wnuczki... z pewnością nie ma się czego bać ze strony tej słodkiej, siwowłosej babuni!', '', 0),
(15361, 'plPL', 'Ale nie dajcie sobie mydlić oczu! Przekonajcie się sami, co kryje się pod tą kołdrą! A teraz... zaczynamy przedstawienie!', '', 0),
(15362, 'plPL', 'Dziś wieczorem zgłębimy otchłanie ludzkiej duszy, towarzysząc zagubionej, samotnej dziewczynce, która rozpaczliwie – z pomocą wiernych towarzyszy – próbuje odnaleźć drogę do domu!', '', 0),
(15363, 'plPL', 'Ale ściga ją... nikczemna, złowroga wiedźma!', '', 0),
(15364, 'plPL', 'Czy przeżyje? Czy zwycięży? Czas pokaże. A teraz... zaczynamy przedstawienie!', '', 0),
(15365, 'plPL', 'Dziś wieczorem... opowieść o zakazanej miłości!', '', 0),
(15366, 'plPL', 'Ale strzeżcie się, bo nie wszystkie historie miłosne kończą się szczęśliwie, o czym możecie się przekonać. Czasem miłość kłuje jak cierń!', '', 0),
(15367, 'plPL', 'Ale nie wierzcie mi na słowo – zobaczcie sami, jaka tragedia czeka, gdy skrzyżują się ścieżki kochanków, którym gwiazdy nie sprzyjają! A teraz... zaczynamy przedstawienie!', '', 0),
(18411, 'plPL', 'Co to za miejsce?', 'Co to za miejsce?', 0),
(18412, 'plPL', 'Gdzie jest Medivh?', 'Gdzie jest Medivh?', 0),
(18413, 'plPL', 'Jak poruszać się po wieży?', 'Jak poruszać się po wieży?', 0),
(18414, 'plPL', 'To wieża Karazhan, siedziba mojego mistrza, Medivha. Jako skromny odźwierny niewiele więcej mogę ci wyjaśnić.', '', 0),
(18415, 'plPL', 'Wszelkie pytania dotyczące Medivha należy kierować do Moriosa, Zarządcy wieży. Ja sam niewiele wiem o sprawach Mistrza. Zdaje się, że kilku szlachciców ma właśnie audiencję u Moriosa w Sali Bankietowej, jeśli chcesz się dowiedzieć więcej.', '', 0),
(18416, 'plPL', 'Stąd, z wartowni, możesz pójść w jednym z trzech kierunków. Schody za mną prowadzą do Wielkiej Sali Balowej, gdzie właśnie bawią się goście. Na pewno czujesz zapach pobliskich stajni, a wejście do Kwater Służby jest obok drzwi wartowni.', '', 0),
(18417, 'plPL', 'Kim jest Północ?', 'Kim jest Północ?', 0),
(18418, 'plPL', 'Północ to osobisty wierzchowiec Łowczego Attumena. Nigdy nie widziałem szybszego, silniejszego ani bardziej złośliwego konia. A jej jeździec ma jeszcze gorszy charakter! Wszyscy trzymają się od niej z daleka, żeby nie oberwać kopytem od Północy albo nie dostać lania od Attumena.', '', 0),
(18419, 'plPL', 'Te przeklęte pająki, bez końca skrzeczące nietoperze i te cholerne demoniczne bestie zagnieździły się w Kwaterach Służby. Nie da się już tam bezpiecznie chodzić, zwłaszcza kiedy te wielkie wychodzą z kryjówek.', '', 0),
(18420, 'plPL', 'W czym mam ci pomóc?', 'W czym mam ci pomóc?', 0),
(18421, 'plPL', 'Te wielkie?', 'Te wielkie?', 0),
(18422, 'plPL', 'O tak, sam ich nigdy nie widziałem, ale czasem słyszę je w oddali. Jeśli zapuścisz się do środka, miej oczy szeroko otwarte.', '', 0),
(18423, 'plPL', 'Nie mam czasu na pogaduszki. Muszę szkolić ludzi i pilnować wieży.', '', 0),
(18424, 'plPL', 'Witaj! Oto jeden z najwspanialszych instrumentów muzycznych w całym Lordaeronie. Występ dla Mistrza i jego gości to prawdziwy zaszczyt. Zajmij miejsce na widowni, podobno zaraz zaczyna się przedstawienie.', '', 0),
(18426, 'plPL', 'To przyjęcie nie ma sensu. Ci głupi szlachcice nigdy nie zobaczą Medivha. Nie widzą tego? Trzeba było zostać z rodziną w Mrocznych Włościach, zamiast marnować tu czas.', '', 0),
(18430, 'plPL', 'Ach, cóż za dziwne miejsce na potencjalnych klientów!', '', 0),
(18431, 'plPL', 'Co możesz sprzedawać?', 'Co możesz sprzedawać?', 0),
(19286, 'plPL', '<Żywiołak wody jest gotów do natarcia.>', '', 0),
(19287, 'plPL', '<Szarżownik stoi dumnie, spragniony bitwy.>', '', 0),
(19292, 'plPL', '<Kleryk zerka na ciebie kątem oka.>', '', 0),
(19294, 'plPL', '<Zaklinacz stoi groźnie, z nieobecnym spojrzeniem.>', '', 0),
(19296, 'plPL', '<Prawdziwa mądrość i siła Llane\'a płoną jasno, nawet w tej podobiźnie króla.>', '', 0),
(19319, 'plPL', '<Siepaczowi cieknie ślinka na myśl o rozlewie krwi.>', '', 0),
(19322, 'plPL', '<Przyzwany demon drga, walcząc z zasadami gry Medivha. Chce twojej duszy!>', '', 0),
(19366, 'plPL', '<Od nekrolity bije mroczna magia.>', '', 0),
(19374, 'plPL', '<Na widok zastygłego, warczącego pyska orkowego wilka przechodzą cię ciarki.>', '', 0),
(19376, 'plPL', '<W oczach czarnoksiężnika tli się głęboka złośliwość.>', '', 0),
(19383, 'plPL', '<Wódz Czarnoręki góruje nad polem.>', '', 0),
(19617, 'plPL', 'Aby przejść dalej przez moją Salę, musisz mnie pokonać w grze zręczności! Gdy będziesz $ggotów:gotowa;, przejmij kontrolę nad swoim królem...', '', 0),
(19877, 'plPL', '%s wpada w szał podsycany Otchłanią!', '', 0),
(19880, 'plPL', '%s krzyczy w głodzie, otwierając bramy do Otchłani.', '', 0),
(20023, 'plPL', 'Nędzne robactwo. Wytępię was z powietrza!', '', 0),
(20425, 'plPL', 'Skoro mnie $gpokonałeś:pokonałaś;, zmierzcie się teraz ze sobą! Przejmij kontrolę nad którymkolwiek królem, by zacząć grę.', '', 0),
(20430, 'plPL', 'Sale Karazhanu drżą, gdy klątwa więżąca drzwi Sali Gracza zostaje zdjęta.', '', 0),
(20519, 'plPL', 'Przenieś mnie, proszę, do Biblioteki Strażnika.', 'Przenieś mnie, proszę, do Biblioteki Strażnika.', 0),
(21910, 'plPL', 'Echo Medivha oszukuje!', '', 0),
(22914, 'plPL', 'Wracaj w zimny mrok!', '', 0),
(24548, 'plPL', '%s bierze głęboki oddech.', '%s bierze głęboki oddech.', 0),
(27712, 'plPL', 'Pijcie, śmiertelnicy! Skosztujcie mojej krwi! Skosztujcie własnej śmierci!', 'Pijcie, śmiertelnicy! Skosztujcie mojej krwi! Skosztujcie własnej śmierci!', 0),
(27780, 'plPL', 'Czuję zapach... $r. Wyśmienicie!', '', 0),
(27781, 'plPL', 'Pochłonę cię!', '', 0),
(35360, 'plPL', 'Z przyjemnością.', '', 0),
(76675, 'plPL', 'Hmm.', '', 0);
